// Increments the Android `versionCode` in app.json.
// Google Play rejects an .aab whose versionCode already exists, so bump this
// before every upload. Pass `--name 1.2.0` to also set the user-facing version.
//
// This edits app.json, NOT android/app/build.gradle. The native project is
// gitignored and regenerated by `expo prebuild`, which build:aab now runs — so
// a bump written into build.gradle is overwritten by the very next prebuild and
// silently lost. app.json is the source prebuild reads from, and it is tracked
// in git, so the version history stops living in a generated file.
const fs = require("fs");
const path = require("path");

const appJsonPath = path.join(__dirname, "..", "app.json");
let raw = fs.readFileSync(appJsonPath, "utf8");

const codeMatch = raw.match(/"versionCode"\s*:\s*(\d+)/);
if (!codeMatch) {
  console.error('Could not find "versionCode" in app.json (expo.android.versionCode)');
  process.exit(1);
}
const nextCode = parseInt(codeMatch[1], 10) + 1;
raw = raw.replace(/"versionCode"\s*:\s*\d+/, `"versionCode": ${nextCode}`);

// Targeted string edits rather than JSON.parse/stringify, so the file keeps its
// existing formatting and key order instead of being rewritten wholesale.
const nameFlag = process.argv.indexOf("--name");
let nameMsg = "";
if (nameFlag !== -1 && process.argv[nameFlag + 1]) {
  const nextName = process.argv[nameFlag + 1];
  if (!/^\d+\.\d+\.\d+$/.test(nextName)) {
    console.error(`--name must look like 1.2.0, got "${nextName}"`);
    process.exit(1);
  }
  // Only the first "version" key, which is expo.version.
  raw = raw.replace(/"version"\s*:\s*"[^"]*"/, `"version": "${nextName}"`);
  nameMsg = `, version -> "${nextName}"`;
}

fs.writeFileSync(appJsonPath, raw);
console.log(`versionCode -> ${nextCode}${nameMsg}`);
console.log("(app.json is tracked — commit this alongside the release)");
